def AmpBoundOfContDiffStatement : Prop :=
  ∀ (n : ℕ) (K : Set (ℝ × ℝ)) (A : ℝ × ℝ → ℂ), IsCompact K → ContDiff ℝ n A → tsupport A ⊆ K →
    ∃ M : ℝ, AmpBound n K A M

def DddEqIteratedStatement : Prop :=
  ∀ (Ψ : ℝ × ℝ → ℝ) (k : ℝ × ℝ), ContDiffAt ℝ 3 Ψ k →
    ∀ u v w, ddd Ψ k u v w = iteratedFDeriv ℝ 3 Ψ k ![u, v, w]

def CubicCoeffsEqStatement : Prop :=
  ∀ φ : ℝ × ℝ → ℝ, ContDiffAt ℝ 3 φ 0 →
    ∀ κ : ℝ × ℝ, cubicForm (cubicCoeffs φ) κ = iteratedFDeriv ℝ 3 φ 0 ![κ, κ, κ] / 6

def FamilyCkOfUncurryStatement : Prop :=
  ∀ (E : Type) [NormedAddCommGroup E] [NormedSpace ℝ E] (n : ℕ) (Ψ : E → ℝ × ℝ → ℝ),
    ContDiff ℝ n (Function.uncurry Ψ) → ∀ S : Set E, FamilyCk n (fun σ : S => Ψ σ)

def LatticeLaplacianLimitStatement : Prop :=
  Tendsto (fun n : ℕ => (((n : ℝ) ^ ((2 : ℝ) / 3) : ℝ) : ℂ) * (-1 : ℂ) ^ n * latticeKernel n ((n : ℤ), (n : ℤ)))
    atTop (𝓝 (d4ClosedConstant (-1 / 48) : ℂ))
